import {CAMPAIGN,MATERIALS,SITES} from './registry.js';
export const SAVE_KEY='qinghe_arg_save',LEGACY_KEY='qinghe_arg_legacy_v4_snapshot',RECOVERY_KEY='qinghe_arg_recovery_v4';
export const empty=()=>({schema:1,campaign:CAMPAIGN,clock:0,discovered_sites:['forum'],evidence:{},snapshots:{},legacyImports:{},accounts:{},hypotheses:{},marks:{},notes:{},timeline:{},preferences:{}});
const buckets=['evidence','snapshots','legacyImports','accounts','hypotheses','marks','notes','timeline','preferences'];
const safeKey=k=>/^[a-zA-Z0-9_-]{1,90}$/.test(k)&&!['__proto__','constructor','prototype'].includes(k);
export function parseJSON(raw){try{return typeof raw==='string'?JSON.parse(raw):raw;}catch{return null;}}
export function validateState(value){const x=parseJSON(value);if(x?.schema!==1||x.campaign!==CAMPAIGN||!Number.isSafeInteger(x.clock)||x.clock<0)return null;const out=empty();for(const site of Array.isArray(x.discovered_sites)?x.discovered_sites:[])if(Object.hasOwn(SITES,site)&&!out.discovered_sites.includes(site))out.discovered_sites.push(site);for(const b of buckets){if(['snapshots','legacyImports'].includes(b)&&!x[b])continue;if(!x[b]||typeof x[b]!=='object'||Array.isArray(x[b]))return null;for(const [id,e]of Object.entries(x[b]).slice(0,500)){if(!safeKey(id)||!Number.isSafeInteger(e?.tick)||e.tick<0||typeof e.actor!=='string'||e.actor.length>90)continue;let v=e.value;if(b==='evidence'&&(!Object.hasOwn(MATERIALS,id)||v!==true)||b==='accounts'&&(!['editor','sports'].includes(id)||v!==true))continue;if(b==='legacyImports'&&(!v||typeof v.raw!=='string'||v.raw.length>1000000||typeof v.sha256!=='string'||v.sha256!==id))continue;if(b==='snapshots'&&(!Object.hasOwn(MATERIALS,id)||!v||typeof v.text!=='string'||v.text.length>16000||typeof v.url!=='string'||v.url.length>500))continue;if(b==='notes'&&(typeof v!=='string'||v.length>12000))continue;if(b==='marks'&&(!Array.isArray(v)||v.length>40||v.some(k=>typeof k!=='string'||k.length>100)))continue;if(b==='timeline'&&(typeof v!=='string'||v.length>100))continue;if(b==='preferences'&&typeof v!=='boolean')continue;if(b==='hypotheses'&&(v!==null&&(!v||typeof v.question!=='string'||typeof v.stance!=='string'||typeof v.note!=='string'||v.note.length>3000||!Array.isArray(v.sources)||v.sources.length>34||v.sources.some(k=>!Object.hasOwn(MATERIALS,k)))))continue;out[b][id]={value:v,tick:e.tick,actor:e.actor};out.clock=Math.max(out.clock,e.tick);}}out.clock=Math.max(out.clock,x.clock);return out;}
export function merge(a,b){a=validateState(a)||empty();b=validateState(b)||empty();const out=empty();out.clock=Math.max(a.clock,b.clock);out.discovered_sites=[...new Set([...a.discovered_sites,...b.discovered_sites])];for(const bucket of buckets)for(const id of new Set([...Object.keys(a[bucket]),...Object.keys(b[bucket])])){const x=a[bucket][id],y=b[bucket][id];out[bucket][id]=!x?y:!y?x:x.tick!==y.tick?(x.tick>y.tick?x:y):x.actor!==y.actor?(x.actor>y.actor?x:y):JSON.stringify(x.value)>=JSON.stringify(y.value)?x:y;}return out;}
export function extract(raw){const root=parseJSON(raw);return root?.save_schema===4&&root.active_campaign===CAMPAIGN?validateState(root.campaigns?.[CAMPAIGN]):null;}
export function legacyProjection(raw){const x=parseJSON(raw);if(x?.version===3){const {save_schema,active_campaign,campaigns,...legacy}=x;return legacy;}return {version:3,clock:0,discovered_sites:['forum'],evidence:{},deductions:{},accounts:{},actions:{},links:{},prefs:{},notes:{},marks:{},vault:null};}
export function envelope(state,current){return {...legacyProjection(current),save_schema:4,active_campaign:CAMPAIGN,campaigns:{[CAMPAIGN]:validateState(state)||empty()}};}
export function edit(state,bucket,id,value,actor){if(!buckets.includes(bucket)||!safeKey(id))throw new Error('无效的调查记录');const next=structuredClone(state);next.clock++;next[bucket][id]={value,tick:next.clock,actor};const checked=validateState(next);if(!checked||JSON.stringify(checked[bucket][id]?.value)!==JSON.stringify(value))throw new Error('调查记录格式不正确');return checked;}
export async function digest(text){const b=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(text));return Array.from(new Uint8Array(b),v=>v.toString(16).padStart(2,'0')).join('');}
export async function pack(raw){return {raw,sha256:await digest(raw)};}
export async function unpack(packed){if(typeof packed?.raw!=='string'||packed.raw.length>2500000||typeof packed.sha256!=='string'||await digest(packed.raw)!==packed.sha256)return null;return packed.raw;}
